import {
  boolean,
  date,
  integer,
  pgTable,
  serial,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

/**
 * Every content table carries a `section` column so the same table serves
 * the temple, the Dhamma school and the Montessori:
 *   "temple" | "dhamma" | "montessori"
 */

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  // Auto-generated registration number, e.g. PKT-2026-0001
  memberNo: text("member_no").unique(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  phone: text("phone").notNull().default(""),
  address: text("address").notNull().default(""),
  avatarUrl: text("avatar_url").notNull().default(""),
  lastSeenAt: timestamp("last_seen_at"),
  // super_admin | temple | dhamma | montessori | member
  role: text("role").notNull().default("member"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Per-section settings: contact details, social accounts and live streaming */
export const sectionSettings = pgTable("section_settings", {
  section: text("section").primaryKey(), // temple | dhamma | montessori
  phone: text("phone").notNull().default(""),
  email: text("email").notNull().default(""),
  whatsapp: text("whatsapp").notNull().default(""), // principal / office
  teacherWhatsapp: text("teacher_whatsapp").notNull().default(""),
  address: text("address").notNull().default(""),
  mapQuery: text("map_query").notNull().default(""), // Google Maps search text or "lat,lng"
  facebookUrl: text("facebook_url").notNull().default(""),
  youtubeUrl: text("youtube_url").notNull().default(""),
  youtubeChannelId: text("youtube_channel_id").notNull().default(""), // UC... for the live player
  instagramUrl: text("instagram_url").notNull().default(""),
  tiktokUrl: text("tiktok_url").notNull().default(""),
  isLive: boolean("is_live").notNull().default(false),
  liveUrl: text("live_url").notNull().default(""), // Facebook or YouTube live video link
  liveTitle: text("live_title").notNull().default(""),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

/** One-time 6-digit codes for resetting a password */
export const passwordResets = pgTable("password_resets", {
  id: serial("id").primaryKey(),
  userId: integer("user_id").notNull(),
  codeHash: text("code_hash").notNull(),
  // user = requested on the website, admin = generated by an admin
  requestedBy: text("requested_by").notNull().default("user"),
  expiresAt: timestamp("expires_at").notNull(),
  usedAt: timestamp("used_at"),
  attempts: integer("attempts").notNull().default(0),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Notices, news and advertisements */
export const posts = pgTable("posts", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  // notice | advertisement | news
  kind: text("kind").notNull().default("notice"),
  title: text("title").notNull(),
  body: text("body").notNull().default(""),
  imageUrl: text("image_url").notNull().default(""),
  linkUrl: text("link_url").notNull().default(""),
  pinned: boolean("pinned").notNull().default(false),
  publishedAt: date("published_at").defaultNow().notNull(),
  expiresAt: date("expires_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Activities / events: dana, pirith, bodhi puja, children's activities ... */
export const events = pgTable("events", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  category: text("category").notNull().default("other"),
  title: text("title").notNull(),
  description: text("description").notNull().default(""),
  eventDate: date("event_date"),
  startTime: text("start_time").notNull().default(""),
  endTime: text("end_time").notNull().default(""),
  schedule: text("schedule").notNull().default(""), // e.g. "Every Poya day"
  location: text("location").notNull().default(""),
  host: text("host").notNull().default(""), // dayaka / sponsoring family
  preacher: text("preacher").notNull().default(""), // monk delivering the bana
  preacherFrom: text("preacher_from").notNull().default(""), // the preacher's temple
  allowRegistration: boolean("allow_registration").notNull().default(false),
  // JSON timetable: [{ time, activity, monk, from }]
  agenda: text("agenda").notNull().default("[]"),
  imageUrl: text("image_url").notNull().default(""),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const galleryItems = pgTable("gallery_items", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  album: text("album").notNull().default(""),
  title: text("title").notNull().default(""),
  description: text("description").notNull().default(""),
  imageUrl: text("image_url").notNull(),
  takenAt: date("taken_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Videos: Katina, Bodhi Puja, Bana ... (YouTube / Facebook / direct .mp4 links) */
export const videos = pgTable("videos", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  category: text("category").notNull().default("bana"),
  title: text("title").notNull(),
  videoUrl: text("video_url").notNull(),
  description: text("description").notNull().default(""),
  recordedAt: date("recorded_at"),
  featured: boolean("featured").notNull().default(false),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const teachers = pgTable("teachers", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  name: text("name").notNull(),
  position: text("position").notNull().default(""),
  subject: text("subject").notNull().default(""),
  phone: text("phone").notNull().default(""),
  email: text("email").notNull().default(""),
  imageUrl: text("image_url").notNull().default(""),
  bio: text("bio").notNull().default(""),
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const students = pgTable("students", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  admissionNo: text("admission_no").notNull().default(""),
  name: text("name").notNull(),
  grade: text("grade").notNull().default(""),
  age: integer("age"),
  guardianName: text("guardian_name").notNull().default(""),
  contact: text("contact").notNull().default(""),
  imageUrl: text("image_url").notNull().default(""),
  achievement: text("achievement").notNull().default(""),
  // Only students with this flag appear on the public site (name, class, photo, achievement)
  showOnWebsite: boolean("show_on_website").notNull().default(false),
  active: boolean("active").notNull().default(true),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Online student registration (Dhamma School / Montessori admissions) */
export const applications = pgTable("applications", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(), // dhamma | montessori
  userId: integer("user_id"),
  childName: text("child_name").notNull(),
  dateOfBirth: date("date_of_birth"),
  gender: text("gender").notNull().default(""),
  grade: text("grade").notNull().default(""),
  schoolName: text("school_name").notNull().default(""),
  parentName: text("parent_name").notNull(),
  relationship: text("relationship").notNull().default(""),
  phone: text("phone").notNull(),
  email: text("email").notNull().default(""),
  address: text("address").notNull().default(""),
  notes: text("notes").notNull().default(""), // medical / special needs
  photoUrl: text("photo_url").notNull().default(""),
  // pending | accepted | waiting | rejected
  status: text("status").notNull().default("pending"),
  admissionNo: text("admission_no").notNull().default(""),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Prefect board and class monitors */
export const leaders = pgTable("leaders", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  // prefect | monitor
  type: text("type").notNull().default("prefect"),
  name: text("name").notNull(),
  position: text("position").notNull().default(""),
  grade: text("grade").notNull().default(""),
  year: integer("year"),
  imageUrl: text("image_url").notNull().default(""),
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const testimonials = pgTable("testimonials", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  userId: integer("user_id"),
  name: text("name").notNull(),
  rating: integer("rating").notNull().default(5),
  message: text("message").notNull(),
  approved: boolean("approved").notNull().default(false),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const messages = pgTable("messages", {
  id: serial("id").primaryKey(),
  section: text("section").notNull(),
  userId: integer("user_id"),
  reply: text("reply").notNull().default(""), // admin reply, shown in the member's account
  name: text("name").notNull(),
  email: text("email").notNull().default(""),
  phone: text("phone").notNull().default(""),
  subject: text("subject").notNull().default(""),
  message: text("message").notNull(),
  isRead: boolean("is_read").notNull().default(false),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/** Daily dana roster: one donor per day per slot (morning / noon / evening) */
export const dailyDana = pgTable(
  "daily_dana",
  {
    id: serial("id").primaryKey(),
    danaDate: date("dana_date").notNull(),
    // morning | noon | evening
    slot: text("slot").notNull(),
    donor: text("donor").notNull(),
    phone: text("phone").notNull().default(""),
    notes: text("notes").notNull().default(""),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [uniqueIndex("daily_dana_date_slot").on(t.danaDate, t.slot)]
);

/** Registrations for Poya sil, Bodhi puja and other programmes */
export const registrations = pgTable("registrations", {
  id: serial("id").primaryKey(),
  section: text("section").notNull().default("temple"),
  eventId: integer("event_id").notNull(),
  userId: integer("user_id"),
  name: text("name").notNull(),
  phone: text("phone").notNull(),
  people: integer("people").notNull().default(1),
  notes: text("notes").notNull().default(""),
  // registered | attended | cancelled
  status: text("status").notNull().default("registered"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const danaBookings = pgTable("dana_bookings", {
  id: serial("id").primaryKey(),
  section: text("section").notNull().default("temple"),
  userId: integer("user_id"), // set when a logged-in member books
  name: text("name").notNull(),
  phone: text("phone").notNull(),
  email: text("email").notNull().default(""),
  danaDate: date("dana_date").notNull(),
  // breakfast | noon | evening_gilanpasa | bodhi_puja | pirith | other
  danaType: text("dana_type").notNull().default("noon"),
  notes: text("notes").notNull().default(""),
  // pending | confirmed | cancelled
  status: text("status").notNull().default("pending"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});
